from pathlib import Path
root=Path(__file__).resolve().parents[2]/'evidence/deer-frame-study/continuity-test';paths=sorted((root/'generated-frames').glob('frame-*.png'));first=cv2.imread(str(paths[0]));h,w=first.shape[:2];sift=cv2.SIFT_create(nfeatures=5000);mask=np.zeros((h,w),np.uint8);mask[int(h*.74):]=255;k0,d0=sift.detectAndCompute(first,mask);matcher=cv2.BFMatcher();points=np.float32([[w*.47,h*.886],[w*.63,h*.838],[w*.865,h*.895]])
