 im=cv2.imread(str(path));k1,d1=sift.detectAndCompute(im,mask);pairs=matcher.knnMatch(d0,d1,k=2);good=[a for a,b in pairs if a.distance<.68*b.distance];a=np.float32([k0[m.queryIdx].pt for m in good]);b=np.float32([k1[m.trainIdx].pt for m in good]);mat,inliers=cv2.estimateAffinePartial2D(a,b,method=cv2.RANSAC,ransacReprojThreshold=2.5);q=cv2.transform(points[None],mat)[0];delta=np.linalg.norm(q-points,axis=1);rows.append({'frame':i+1,'ground_matches':len(good),'ground_inliers':int(inliers.sum()),'scale':float(np.hypot(mat[0,0],mat[0,1])),'rotation_deg':float(np.degrees(np.arctan2(mat[1,0],mat[0,0]))),'translation_px':mat[:,2].tolist(),'max_ground_anchor_displacement_px':float(delta.max())})
